 :root {
   color-scheme: dark;
   --bg: #0b1020;
   --panel: #11182b;
   --panel-border: #26304c;
   --text: #edf2ff;
   --muted: #a8b3d6;
   --accent: #7c9cff;
   --accent-strong: #9eb5ff;
   --error: #ff8da1;
   --error-bg: rgba(255, 141, 161, 0.12);
   --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
 }

 *,
 *::before,
 *::after {
   box-sizing: border-box;
 }

 html {
   background: radial-gradient(circle at top, #17213d 0, var(--bg) 55%);
 }

 body {
   margin: 0;
   min-height: 100vh;
   font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
   color: var(--text);
   line-height: 1.5;
 }

 .skip-link {
   position: absolute;
   top: 0.75rem;
   left: 0.75rem;
   padding: 0.75rem 1rem;
   border-radius: 0.75rem;
   background: #ffffff;
   color: #111827;
   transform: translateY(-160%);
   transition: transform 0.2s ease;
   z-index: 10;
 }

 .skip-link:focus {
   transform: translateY(0);
   outline: 3px solid var(--accent);
   outline-offset: 2px;
 }

 .page-main {
   min-height: 100vh;
   display: grid;
   place-items: center;
   padding: 2rem 1rem;
 }

 .support-card {
   width: min(100%, 42rem);
   background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02)), var(--panel);
   border: 1px solid var(--panel-border);
   border-radius: 1.5rem;
   box-shadow: var(--shadow);
   padding: clamp(1.5rem, 4vw, 2.25rem);
 }

 .eyebrow {
   margin: 0 0 0.5rem;
   color: var(--accent-strong);
   font-size: 0.875rem;
   font-weight: 700;
   letter-spacing: 0.12em;
   text-transform: uppercase;
 }

 h1 {
   margin: 0;
   font-size: clamp(1.75rem, 4vw, 2.5rem);
   line-height: 1.1;
 }

 .intro {
   margin: 0.75rem 0 1.75rem;
   color: var(--muted);
   max-width: 55ch;
 }

 form {
   display: grid;
   gap: 1rem;
 }

 .form-field {
   display: grid;
   gap: 0.45rem;
 }

 label {
   font-weight: 600;
 }

 .required-mark {
   color: var(--accent-strong);
 }

 input {
   width: 100%;
   appearance: none;
   border: 1px solid #35425f;
   border-radius: 0.9rem;
   background: #0e1527;
   color: var(--text);
   padding: 0.9rem 1rem;
   font: inherit;
   transition: border-color 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
 }

 input::placeholder {
   color: #7784a9;
 }

 input:hover {
   border-color: #4a5b83;
 }

 input:focus {
   outline: none;
   border-color: var(--accent);
   box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.18);
 }

 input[aria-invalid="true"] {
   border-color: var(--error);
   background: #1a1020;
 }

 .field-help {
   margin: 0;
   color: var(--muted);
   font-size: 0.95rem;
 }

 .field-error {
   margin: 0;
   min-height: 1.4em;
   color: var(--error);
   font-size: 0.95rem;
   font-weight: 600;
 }

 .field-error:not(:empty) {
   padding: 0.65rem 0.8rem;
   border-radius: 0.75rem;
   background: var(--error-bg);
 }

 .submit-button {
   justify-self: start;
   border: 0;
   border-radius: 0.9rem;
   padding: 0.95rem 1.35rem;
   background: linear-gradient(180deg, #8ba7ff, #6f8eff);
   color: #07101f;
   font: inherit;
   font-weight: 700;
   cursor: pointer;
   transition: transform 0.15s ease, box-shadow 0.15s ease, filter 0.15s ease;
   box-shadow: 0 14px 30px rgba(111, 142, 255, 0.26);
 }

 .submit-button:hover {
   filter: brightness(1.05);
   transform: translateY(-1px);
 }

 .submit-button:focus {
   outline: 3px solid #d7e1ff;
   outline-offset: 3px;
 }

 @media (max-width: 480px) {
   .page-main {
     padding: 1rem;
   }

   .support-card {
     border-radius: 1.1rem;
   }

   .submit-button {
     width: 100%;
     justify-self: stretch;
   }
 }

 @media (forced-colors: active) {
   .skip-link,
   .support-card,
   input,
   .submit-button {
     forced-color-adjust: none;
   }

   .skip-link {
     background: Canvas;
     color: CanvasText;
     border: 1px solid CanvasText;
   }

   .support-card {
     background: Canvas;
     border-color: CanvasText;
   }

   input {
     background: Canvas;
     color: CanvasText;
     border-color: CanvasText;
   }

   .field-error,
   .field-help {
     color: CanvasText;
   }

   .submit-button {
     background: ButtonFace;
     color: ButtonText;
     border: 1px solid ButtonText;
     box-shadow: none;
   }
 }

')

