         <div class="form-field">
           <label for="phone-number">Phone number</label>
           <input
             id="phone-number"
             name="phoneNumber"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-number-help phone-number-error"
           >
           <p class="field-help" id="phone-number-help">Optional. Use a format like +1 555 123 4567 or (555) 123-4567.</p>
           <p class="field-error" id="phone-number-error" aria-live="polite"></p>
         </div>

         <button type="submit" class="submit-button">Send message</button>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');

     const fields = {
       fullName: {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate: (value) => {
           if (!value.trim()) {
             return 'Error: Full name is required.';
           }

           return '';
         },
       },
       emailAddress: {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate: (value) => {
           if (!value.trim()) {
             return 'Error: Email address is required.';
           }

           if (!fields.emailAddress.input.validity.valid) {
             return 'Error: Enter a valid email address.';
           }

           return '';
         },
       },
       phoneNumber: {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         validate: (value) => {
           if (!value.trim()) {
             return '';
           }

           const phonePattern = /^(\+?\d{1,3}[-.\s]?)?(\(?\d{3}\)?[-.\s]?)\d{3}[-.\s]?\d{4}$/;

           if (!phonePattern.test(value.trim())) {
             return 'Error: Use a phone number like +1 555 123 4567 or (555) 123-4567.';
           }

           return '';
         },
       },
     };

     const setFieldState = (field, message) => {
       const hasError = Boolean(message);

       field.error.textContent = message;
       field.input.setAttribute('aria-invalid', hasError ? 'true' : 'false');
       field.error.hidden = !hasError;
     };

     const validateField = (field) => {
       const message = field.validate(field.input.value);
       setFieldState(field, message);
       return !message;
     };

     Object.values(fields).forEach((field) => {
       field.error.hidden = true;

       field.input.addEventListener('blur', () => {
         validateField(field);
       });

       field.input.addEventListener('input', () => {
         if (field.error.hidden === false) {
           validateField(field);
         }
       });
     });

     form.addEventListener('submit', (event) => {
       const isValid = Object.values(fields).every(validateField);

       if (!isValid) {
         event.preventDefault();

         const firstInvalid = Object.values(fields).find((field) => field.input.getAttribute('aria-invalid') === 'true');
         firstInvalid?.input.focus();
       }
     });
   </script>
 </body>
 </html>

